const crypto = require('crypto');

// รหัสเข้าเว็บ ตั้งที่ Vercel > Settings > Environment Variables ชื่อ SITE_PIN
const PIN = String(process.env.SITE_PIN || '2217');
const COOKIE = 'db_session';
const MAX_AGE = 60 * 60 * 24 * 30;
const TOKEN = crypto.createHash('sha256').update('droidbench|' + PIN).digest('hex');

// ---- ดึงรายชื่อเครื่องจากฐานข้อมูลสาธารณะของ Google อัตโนมัติ ----
const CSV_URL = 'https://storage.googleapis.com/play_public/supported_devices.csv';
let CATCACHE = { at: 0, data: null };
function splitCsvLine(line, sep) {
  const out = []; let cur = ''; let q = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (q) { if (ch === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else q = false; } else cur += ch; }
    else if (ch === '"') q = true;
    else if (ch === sep) { out.push(cur); cur = ''; }
    else cur += ch;
  }
  out.push(cur); return out;
}
function parseGoogleCsv(text) {
  text = text.replace(/^\uFEFF/, '');
  const lines = text.split(/\r?\n/);
  if (!lines.length) return [];
  const sep = (lines[0].split('\t').length > lines[0].split(',').length) ? '\t' : ',';
  const map = new Map();
  for (let i = 1; i < lines.length; i++) {
    if (!lines[i]) continue;
    const r = splitCsvLine(lines[i], sep);
    const brand = (r[0] || '').trim(), name = (r[1] || '').trim(), device = (r[2] || '').trim(), model = (r[3] || '').trim();
    if (!brand || (!name && !device && !model)) continue;
    const key = (brand + '|' + name + '|' + device).toLowerCase();
    let e = map.get(key);
    if (!e) { e = [brand, name || device || model, device, []]; map.set(key, e); }
    if (model && !e[3].includes(model)) e[3].push(model);
  }
  return [...map.values()];
}
async function getCatalog() {
  if (CATCACHE.data && Date.now() - CATCACHE.at < 12 * 3600 * 1000) return CATCACHE;
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 8000);
  try {
    const res = await fetch(CSV_URL, { signal: ctrl.signal });
    if (res.ok) {
      const buf = Buffer.from(await res.arrayBuffer());
      const cat = parseGoogleCsv(buf.toString('utf16le'));
      if (cat.length) CATCACHE = { at: Date.now(), data: cat };
    }
  } catch (e) { /* เก็บแคชเดิมไว้ */ }
  finally { clearTimeout(timer); }
  return CATCACHE;
}

